  FT["PH-H5689"] = {"id":"PH-H5689","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7201_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将邦板牙省Guagua市镇邦板牙省立医院床位由25张增至100张并为此拨款的法案","en":"An Act Increasing the Bed Capacity of the Pampanga Provincial Hospital in the Municipality of Guagua, Province of Pampanga, From Twenty-five (25) to One Hundred (100) Beds, and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Pampanga Provincial Hospital in the Municipality of Guagua, Province of Pampanga, From Twenty-five (25) to One Hundred (100) Beds, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7201","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-02-25","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7201_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5689-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Pampanga Provincial Hospital in the Municipality of Guagua, Province of Pampanga, is hereby increased from twenty-five (25) to one hundred (100) beds."}},{"id":"PH-H5689-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the lump-sum appropriations authorized for the purpose under the current General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5689-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p81","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Pampanga Provincial Hospital in the Municipality of Guagua, Province of Pampanga, From Twenty-five (25) to One Hundred (100) Beds, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5690"] = {"id":"PH-H5690","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7202_1992.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"授权赔偿糖业生产者因政府所有和控制的机构行为而在 1974 至 1985 作物年度遭受损失的法案","en":"An Act Authorizing the Restitution of Losses Suffered By Sugar Producers From Crop Year 1974-1975 to Crop Year 1984-1985 Due to the Actions of Government-owned and Controlled Agencies","orig":"An Act Authorizing the Restitution of Losses Suffered By Sugar Producers From Crop Year 1974-1975 to Crop Year 1984-1985 Due to the Actions of Government-owned and Controlled Agencies"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 7202","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-02-29","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7202_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5690-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"It is hereby declared the policy of the Government to restitute the losses suffered by the sugar producers due to actions taken by government agencies in order to revive the economy in the sugar-producing areas of the country."}},{"id":"PH-H5690-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Whatever amount recovered by the Government through the Presidential Commission on Good Government or any other agency or from any other source and whatever assets or funds that may be recovered, or already recovered, which have been determined to have been stolen or illegally acquired from the sugar industry shall be used to compensate all sugar producers from Crop Year 1974-1975 up to and including Crop Year 1984-1985 on a pro rata basis."}},{"id":"PH-H5690-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Philippine National Bank, the Republic Planters Bank, the Development Bank of the Philippines and other government-owned and controlled financial institutions which have granted loans to the sugar producers shall extend to accounts of said sugar producers incurred from Crop Year 1974-1975 up to and including Crop year 1984-1985 the following:\na. Condonation of interest charged by the banks in excess of twelve percent (12%) per annum and all penalties and sur-charges;\nb. The recomputed loans shall be amortized for a period of thirteen (13) years inclusive of a three-year grace period on principal effective upon the approval of this Act. The principal portion of the loan will carry an interest rate of twelve percent (12%) per annum and on the outstanding balance effective when the original promissory notes were signed and funds released to the producer."}},{"id":"PH-H5690-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Account of sugar producers pertaining to Crop Year 1974-1975 up to the including Crop Year 1984-1985 which have been fully or partially paid, or may have been the subject of restructuring and other similar arrangement with government banks shall be covered by the provisions abovestated. The benefit of this Act shall not be extended to any sugar producer with a pending sequestration or ill-gotten wealth case before any administrative or judicial body. Any recovery shall be placed in escrow until the case has been finally resolved."}},{"id":"PH-H5690-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Accounts of sugar producers pertaining to Crop Year 1974-1975 up to and including Crop Year 1984-1985 with banks under liquidation or receivership by the Central Bank shall likewise be covered by the abovestated provisions."}},{"id":"PH-H5690-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Central Bank of the Philippines shall provide when necessary restructuring banks with adequate refinancing under similar, if not better, terms than that provided in Section 3(b) hereof."}},{"id":"PH-H5690-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The Commission on Audit shall audit and certify the restructuring package and computation of the banks affected."}},{"id":"PH-H5690-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"If any provision of this Act shall be held unconstitutional or invalid, the other provisions not otherwise affected shall remain in full force and effect."}},{"id":"PH-H5690-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Such other rules and regulations as may be necessary for the adequate implementation of this Act shall be promulgated by the Central Bank of the Philippines within sixty (60) days from the effectivity of this Act."}},{"id":"PH-H5690-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"All laws, acts, executive orders and circulars in conflict herewith are hereby repealed or modified accordingly."}},{"id":"PH-H5690-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its publication in two (2) newspapers of general circulation."}}],"pack":"ph-p81","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the Restitution of Losses Suffered By Sugar Producers From Crop Year 1974-1975 to Crop Year 1984-1985 Due to the Actions of Government-owned and Controlled Agencies","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
