  FT["PH-H5710"] = {"id":"PH-H5710","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7222_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将伊洛伊洛省巴拉桑市镇阿兰胡埃斯描笼涯阿兰胡埃斯小学的名称变更为Pedro Bedez小学的法案","en":"An Act Changing the Name of the Aranjuez Elementary School in Barangay Aranjuez, Municipality of Balasan, Province of Iloilo, to Pedro Bedez Elementary School","orig":"An Act Changing the Name of the Aranjuez Elementary School in Barangay Aranjuez, Municipality of Balasan, Province of Iloilo, to Pedro Bedez Elementary School"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7222","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-11","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7222_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5710-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Aranjuez Elementary School in Barangay Aranjuez, Municipality of Balasan, Province of Iloilo, is hereby changed to Pedro Bedez Elementary School."}},{"id":"PH-H5710-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p81","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Aranjuez Elementary School in Barangay Aranjuez, Municipality of Balasan, Province of Iloilo, to Pedro Bedez Elementary School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5711"] = {"id":"PH-H5711","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7223_1992.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":"授予 Gateway 特高频电视广播公司在菲律宾为商业目的建设、安装、运营和维护特高频电视广播站并为其他目的法案","en":"An Act Granting Gateway U.H.F. Television Broadcasting, Inc., a Franchise to Construct, Install, Operate and Maintain for Commercial Purposes Uhf Television Broadcasting Stations in the Philippines, and for Other Purposes","orig":"An Act Granting Gateway U.H.F. Television Broadcasting, Inc., a Franchise to Construct, Install, Operate and Maintain for Commercial Purposes Uhf Television Broadcasting Stations in the Philippines, and for Other Purposes"},"level":"law","status":"active","topics":["investment","trade"],"docNumber":"Republic Act No. 7223","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-11","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7223_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5711-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to Gateway U.H.F. Television Broadcasting, Inc., hereunder referred to as the grantee, its successors or assigns a franchise to construct, install, operate and maintain for commercial purposes and in the public interest UHF television broadcasting stations in the Philippines with the corresponding technological auxiliaries or facilities, special broadcast distribution services and relay stations: Provided, however, That only one (1) UHF channel shall be allocated to any given locality."}},{"id":"PH-H5711-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the existing stations or other stations which may be established in accordance with law of other telecommunications services grantees without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee-s services and/or the availability thereof."}},{"id":"PH-H5711-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H5711-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall provide reasonable public service time to enable the government, through the said UHF television stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H5711-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Rates for Services. - The grantee shall fix just and reasonable rates for subscription, excluding the cost of installation, subject to the regulations of the National Telecommunications Commission and other proper regulatory agencies of the government."}},{"id":"PH-H5711-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Right of Government. - A special right is hereby reserved to the President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations of the grantee, to temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the government upon due compensation to the grantee, for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H5711-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act unless sooner revoked or canceled. In the event the grantee fails to operate continuously for two (2) years from the effectivity of this franchise or anytime thereafter, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H5711-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Public Ownership. - In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make public offering through the stock exchanges of at least thirty percent (30%) of its common stocks within a period of three (3) years from the date of effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offerings."}},{"id":"PH-H5711-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to five percent (5%) of all gross receipts of the television business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code. The return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H5711-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H5711-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Self-regulation by and Undertaking of Grantee. - The grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast and/or telecast from its stations; but if any such speech, play, act or scene, or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play, act or scene, or other matter: Provided, That the grantee, during any broadcast and/or telecast, shall cut off from the air the speech, play, act or scene, or other matter being broadcast/telecast if the tendency thereof is to promote and/or incite treason, rebellion or sedition, or the language used therein or the theme thereof is indecent or immoral; and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H5711-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H5711-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or entity, nor merge with any other corporation or entity without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such private person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is validly sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H5711-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"General Broadcast Policy. - The grantee shall comply with and be subject to the provisions of a general broadcast policy law that may hereafter be enacted."}},{"id":"PH-H5711-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Separability Clause . - if any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H5711-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Repealability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H5711-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p81","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Gateway U.H.F. Television Broadcasting, Inc., a Franchise to Construct, Install, Operate and Maintain for Commercial Purposes Uhf Television Broadcasting Stations in the Philippines, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5712"] = {"id":"PH-H5712","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7224_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将打拉省Concepcion市镇Concepcion区医院床位由25张增至50张并为此拨款的法案","en":"An Act Increasing the Bed Capacity of the Concepcion District Hospital in the Municipality of Concepcion, Province of Tarlac, From Twenty-five (25) to Fifty (50) Beds, and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Concepcion District Hospital in the Municipality of Concepcion, Province of Tarlac, From Twenty-five (25) to Fifty (50) Beds, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7224","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-12","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7224_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5712-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Concepcion District Hospital in the Municipality of Concepcion, Province of Tarlac, is hereby increased from twenty-five (25) to fifty (50) beds."}},{"id":"PH-H5712-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law."}},{"id":"PH-H5712-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p81","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Concepcion District Hospital in the Municipality of Concepcion, Province of Tarlac, From Twenty-five (25) to Fifty (50) Beds, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5713"] = {"id":"PH-H5713","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7225_1992.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"将依第 4339 号共和国法授予 Iglesia Ni Cristo 建设、安装、设立和运营私人电信无线电台的特许权续展二十五年","en":"An Act Extending the Franchise Granted to the Iglesia Ni Cristo to Construct, Install, Establish and Operate Radio Stations for Private Telecommunications Under Republic Act Numbered Forty-three Hundred and Thirty-nine to Another Twenty-five Years","orig":"An Act Extending the Franchise Granted to the Iglesia Ni Cristo to Construct, Install, Establish and Operate Radio Stations for Private Telecommunications Under Republic Act Numbered Forty-three Hundred and Thirty-nine to Another Twenty-five Years"},"level":"law","status":"active","topics":["investment","data"],"docNumber":"Republic Act No. 7225","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-12","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7225_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5713-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The life of the franchise of the Iglesia ni Cristo to construct, install, establish and operate radio stations for private telecommunications under Republic Act Numbered Forty-three hundred and thirty-nine is hereby extended to another twenty-five (25) years from February 10, 1994."}},{"id":"PH-H5713-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All other provisions, terms and conditions contained in Republic Act Numbered Forty-three hundred and thirty-nine which are otherwise not affected hereby are made integral parts of this Act."}},{"id":"PH-H5713-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The franchise hereby granted shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the common good so requires."}},{"id":"PH-H5713-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"In addition to the terms and conditions herein provided, the Iglesia ni Cristo, shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H5713-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee shall comply with and be subject to the provisions of a general telecommunications policy law that may hereafter be enacted."}},{"id":"PH-H5713-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p81","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Extending the Franchise Granted to the Iglesia Ni Cristo to Construct, Install, Establish and Operate Radio Stations for Private Telecommunications Under Republic Act Numbered Forty-three Hundred and Thirty-nine to Another Twenty-five Years","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5714"] = {"id":"PH-H5714","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7226_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"要求审计委员会向国会提交国家政府机构与单位（含政府拥有公司）在各市镇、省与城市已承担款项、已签发支付凭证与已支出款项的年度报告并为其他目的","en":"An Act Requiring the Commission on Audit to Submit to Congress Annual Reports of Amounts Obligated, Warrants Issued, and Expenditures Made in Each Municipality, Province, and City By National Government Agencies, and Instrumentalities, Including Government-owned Corporations, and for Other Purposes","orig":"An Act Requiring the Commission on Audit to Submit to Congress Annual Reports of Amounts Obligated, Warrants Issued, and Expenditures Made in Each Municipality, Province, and City By National Government Agencies, and Instrumentalities, Including Government-owned Corporations, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7226","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-06","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7226_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5714-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"In addition to the financial reports required by existing law to be submitted to Congress, the Commission on Audit shall submit an annual report of the amounts obligated, treasury and funding warrants issued, and expenditures made every quarter during the fiscal year for each municipality, province, and city by all agencies and instrumentalities of the National Government, including government-owned corporations.\nThe annual report shall also contain the same data for each agency and instrumentality of the National Government, including government-owned corporations, by province and highly urbanized city."}},{"id":"PH-H5714-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The annual financial reports herein required shall be submitted to Congress within one hundred twenty (120) days after the end of every fiscal year."}},{"id":"PH-H5714-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p81","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Requiring the Commission on Audit to Submit to Congress Annual Reports of Amounts Obligated, Warrants Issued, and Expenditures Made in Each Municipality, Province, and City By National Government Agencies, and Instrumentalities, Including Government-owned Corporations, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5715"] = {"id":"PH-H5715","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7227_1992.html","fetchedAt":"2026-10-06","articleCount":23,"structureMode":"ARTICLE","title":{"zh":"加快军事保留地转作其他生产用途、为此设立基地转换与发展管理局、提供资金并为其他目的法案","en":"An Act Accelerating the Conversion of Military Revervations Into Other Productive Uses, Creating the Bases Conversion and Development Authority for This Purpose, Providing Funds Therefor and for Other Purposes","orig":"An Act Accelerating the Conversion of Military Revervations Into Other Productive Uses, Creating the Bases Conversion and Development Authority for This Purpose, Providing Funds Therefor and for Other Purposes"},"level":"law","status":"active","topics":["defence"],"docNumber":"Republic Act No. 7227","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-13","completenessNote":"全文，共 23 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7227_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 24 条，缺 8）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5715-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title . - This Act shall be known as the \"Bases Conversion and Development Act of 1992.\""}},{"id":"PH-H5715-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policies. - It is hereby declared the policy of the Government to accelerate the sound and balanced conversion into alternative productive uses of the Clark and Subic military reservations and their extensions (John Hay Station, Wallace Air Station, O'DonneIl Transmitter Station, San Miguel Naval Communications Station and Capas Relay Station), to raise funds by the sale of portions of Metro Manila military camps, and to apply said funds as provided herein for the development and conversion to productive civilian use of the lands covered under the 1947 Military Bases Agreement between the Philippines and the United States of America, as amended.\nIt is likewise the declared policy of the Government to enhance the benefits to be derived from said properties in order to promote the economic and social development of Central Luzon in particular and the country in general."}},{"id":"PH-H5715-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Creation of the Bases Conversion and Development Authority. - There is hereby created a body corporate to be known as the Bases Conversion and Development Authority, hereinafter referred to as the Conversion Authority, which shall have the attribute of perpetual succession and shall be vested with the powers of a corporation.\nIt shall be organized within thirty (30) days after approval of this Act. It shall have a term of fifty (50) years from its organization: Provided, That Congress, by a joint resolution, may dissolve the Conversion Authority whenever in its judgment the primary purpose for its creation has been accomplished. It shall establish its principal office in Metropolitan Manila unless otherwise provided by the Conversion Authority and may put up such branches as may be necessary."}},{"id":"PH-H5715-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Purposes of the Conversion Authority. - The Conversion Authority shall have the following purposes:\na. To own, hold and/or administer the military reservations of John Hay Air Station, Wallace Air Station, O'Donnell Transmitter Station, San Miguel Naval Communications Station, Mt. Sta. Rita Station (Hermosa, Bataan) and those portions of Metro Manila military camps which may be transferred to it by the President;\nb. To adopt, prepare and implement a comprehensive and detailed development plan embodying a list of projects including but not limited to those provided in the Legislative-Executive Bases Council (LEBC) framework plan for the sound and balanced conversion of the Clark and Subic military reservations and their extensions consistent with ecological and environmental standards, into other productive uses to promote the economic and social development of Central Luzon in particular and the country in general;\nc. To encourage the active participation of the private sector in transforming the Clark and Subic military reservations and their extensions into other productive uses;\nd. To serve as the holding company of subsidiary companies created pursuant to Section 16 of this Act and to invest in Special Economic Zones declared under Sections 12 and 15 of this Act;\ne. To manage and operate through private sector companies developmental projects outside the jurisdiction of subsidiary companies and Special Economic Zones declared by presidential proclamations and established under this Act;\nf. To establish a mechanism in coordination with the appropriate local government units to effect meaningful consultation regarding the plans, programs and projects within the regions where such plans, programs and/or project development are part of the conversion of the Clark and Subic military reservations and their extensions and the surrounding communities as envisioned in this Act; and\ng. To plan, program and undertake the readjustment, relocation, or resettlement of population within the Clark and Subic military reservations and their extensions as may be deemed necessary and beneficial by the Conversion Authority, in coordination with the appropriate government agencies and local government units."}},{"id":"PH-H5715-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Powers of the Conversion Authority. - To carry out its objectives under this Act, the Conversion Authority is hereby vested with the following powers:\na. To succeed in its corporate name, to sue and be sued in such corporate name and to adopt, atter and use a corporate seal which shall be judicially noticed;\nb. To adopt, amend and repeal its bylaws;\nc. To enter into, make, perform and carry out contracts of every class, kind and description which are necessary or incidental to the realization of its purposes with any person, firm or corporation, private or public, and with foreign government entities;\nd. To contract loans, indebtedness, credit and issue commercial papers and bonds, in any local or convertible foreign currency from any international financial institutions, foreign government entities, and local or foreign private commercial banks or similar institutions under terms and conditions prescribed by law, rules and regulations;\ne. To execute any deed of guarantee, mortgage, pledge, trust or assignment of any property for the purpose of financing the programs and projects deemed vital for the early attainment of its goals and objectives, subject to the provisions of Article VII, Section 20, and Article XII, Section 2, paragraphs (4) and (5) of the Constitution;\nf. To construct, own, lease, operate and maintain public utilities as well as infrastructure facilities;\ng. To reclaim or undertake reclamation projects as it may deem necessary in areas adjacent or contiguous to the Conversion Authority's lands described in Section 7 of this Act either by itself or in collaboration with the Public Estates Authority (PEA) established under Presidential Decree No. 1084 as amended;\nh. To acquire, own, hold, administer, and lease real and personal properties, including agricultural lands, property rights and interests and encumber, lease, mortgage, sell, alienate or otherwise dispose of the same at fair market value it may deem appropriate;\ni. To receive donations, grants, beguests and assistance of all kinds from local and foreign governments and private sectors and utilize the same;\nj. To invest its funds and other assets other than those of the Special Economic Zones under Sections 12 and 15 of this Act in such areas it may deem wise;\nk. To exercise the right of eminent domain;\nl. To exercise oversight functions over the Special Economic Zones declared under this Act and by subsequent presidential proclamations within the framework of the declared policies of this Act;\nm. To promulgate all necessary rules and regulations; and\nn. To perform such other powers as may be necessary and proper to carry out the purposes of this Act."}},{"id":"PH-H5715-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Capitalization. - The Conversion Authority shall have an authorized capital of One hundred billion pesos (P100,000,000,000) which may be fully subscribed by the Republic of the Philippines and shall either be paid up from the proceeds of the sales of its land assets as provided for in Section 8 of this Act or by transferring to the Conversion Authority properties valued in such amount.\nAn initial operating capital in the amount of Seventy million pesos (P70,000,000) is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated which shall be covered by preferred shares of the Conversion Authority retireable within two (2) years."}},{"id":"PH-H5715-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Transfer of Properties. - Pursuant to paragraph (a), Section 4 hereof, the President shall transfer forthwith to the Conversion Authority;\n(a) Station Area in Has. (more or less) John Hay Air Station 570 Wallace Air Station 167 O'Donnell Transmitter Station 1,755 San Miguel Naval Communications Station 1,100 Mt. Sta. Rita Station (Hermosa, Bataan)\n(b) Such other properties including, but not limited to, portions of Metro Manila military camps, pursuant to Section 8 of this Act: Provided, however, That the areas which shall remain as military reservations shall be delineated and proclaimed as such by the President.\nSection 8 Funding Scheme. - The capital of the Conversion Authority shall come from the sales proceeds and/or transfers of certain Metro Manila military camps, including all lands covered by Proclamation No. 423, series of 1957, commonly known as Fort Bonifacio and Villamor (Nichols) Air Base, namely:\nCamp\nArea in has.\n(more or less) Phase 1 (for immediate disposal)\n1. Camp Claudio\n2.0\n2. Camp Bago Bantay\n5.10\n3. Camp Bago Bantay\n135.10\n4. Part of Fort Bonifacio\n498.40 TOTAL\n640.60 Phase II\n1. Camp Ver\n1.9\n2. Camp Melchor\n1.0\n3. Camp Atienza\n4.9\n4. Part of Villamor Air Base\n37.9\n5. Part of Fort Bonifacio\n224.90\n6. Fort Abad .60 Total\n271.20 : Provided, That the following areas shall be exempt from sale:\na. Approximately 148.80 hectares in Fort Bonifacio for the National Capital Region (NCR) Security Brigade, Philippine Army (PA) officers' housing area, and Philippine National Police (PNP) jails and support services (presently Camp Bagong Diwa);\nb. Approximately 99.91 hectares in Villamor Air Base for the Presidential Airlift Wing, one squadron of helicopters for the NCR and respective security units;\nc. The following areas segregated by Proclamation Nos.:\n1. 461, series of 1965; (AFP Officers Village)\n2. 462, .series of 1965; (AFP Enlisted Men's Village)\n3. 192, series of 1967; (Veterans Center)\n4. 208, series of 1967; (National Shrines)\n5. 469, series of 1969; (Philippine College of Commerce)\n6. 653, series of 1970; (National Manpower and Youth council)\n7. 684, series of 1970; (University Center)\n8. 1041, .series of 1972; (Open Lease Concession)\n9. 1160, series of 1973; (Manila Technical Institute)\n10. 1217, series of 1973; (Maharlika Village)\n11. 682, series of 1970; (Civil Aviation Purposes)\n12. 1048, series of 1975; (Civil Aviation Purposes)\n13. 1453, .series of 1975; (National Police Commission)\n14. 1633, series of 1977; (Housing and Urban Development)\n15. 2219, series of 1982; (Ministry of Human Settlements, BLISS)\n16. 172, series of 1987; (Upper, Lower, and Western Bicutan .and Signal Housing)\n17. 389, series of 1989; (National Mapping and Resource Information Authority)\n18. 518, series of 1990; (CEMBO, SO CEMBO, W REMBO, E REMBO, COMEMBO, PEMBO, PITOGO)\n19. 467, series of 1968; (Greater Manila Terminal Food Market Site)\n20. 347, series of 1968; (Greater Manila Food Market Site)\n21. 376, series of 1968; (National Development Board and Science Community)\nd. A proposed 30.15 hectares as relocation site for families to be affected by circumferential road 5 and radial road 4 construction: Provided, further, That the boundaries and technical descriptions of these exempt areas shall be determined by an actual ground survey.\nThe President is hereby authorized to sell the above lands, in whole or in part, which are hereby declared alienable and disposable pursuant to the provisions of existing laws and regulations governing sales of government properties: Provided, That no sale or disposition of such lands will be undertaken until a development plan embodying projects for conversion shall be approved by the President in accordance with paragraph (b), Section 4, of this Act. However, six (6) months after approval of this Act, the President shall authorize the Conversion Authority to dispose of certain areas in Fort Bonifacio and Villamor as the latter so determines. The Conversion Authority shall provide the President a report on any such disposition or plan for disposition within one (1) month from such disposition or preparation of such plan. The proceeds from any sale, after deducting all expenses related to the sale, of portions of Metro Manila military camps as authorized under this Act, shall be used for the following purposes with their corresponding percent shares of proceeds:\n1. Thirty-two and five-tenths percent (32.5%) - To finance the transfer of the AFP military camps and the construction of new camps, the self-reliance and modernization program of the AFP, the concessional and long-term housing loan assistance and livelihood assistance to AFP officers and enlisted men and their families, and the rehabilitation and expansion of the AFP's medical facilities;\n2. Fifty percent (50%) - To finance the conversion and the commercial uses of the Clark and Subic military reservations and their extensions;\n3. Five percent (5%) - To finance the concessional and long-term housing loan assistance for the homeless of Metro Manila, Olongapo City, Angeles City and other affected municipalities contiguous to the base areas as mandated herein; and\n4. To balance shall accrue and be remitted to the National Treasury to be appropriated thereafter by Congress for the sole purpose of financing programs and projects vital for the economic upliftment of the Filipino people.\nProvided, That, in the case of Fort Bonifacio, two and five tenths percent (2.5%) of the proceeds thereof in equal shares shall each go to the Municipalities of Makati, Taguig and Pateros: Provided, further, That in no case shall farmers affected be denied due compensation.\nWith respect to the military reservations and their extensions, the President upon recommendation of the Conversion Authority or the Subic Authority when it concerns the Subic Special Economic Zone shall likewise be authorized to sell or dispose those portions of lands which the Conversion Authority or the Subic Authority may find essential for the development of their projects."}},{"id":"PH-H5715-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Board of Directors: Composition. - The powers and functions of the Conversion Authority shall be exercised by a Board of Directors to be composed of nine (9) members, as follows:\na. A full-time chairman who shall also be the president of the Conversion Authority; and\nb. Eight (8) other members from the private sector, two (2) of whom coming from the labor sector.\nThe chairman and members shall be appointed by the President with the consent of the Commission on Appointments. Of the initial members of the Board, three (3) including the chairman, a representative from the private sector and a representative from the labor sector shall be appointed for a term of six (6) years, three (3) for a term of four (4) years and the other three (3) for a term of two (2) years. In case of vacancy in the Board, the appointee shall serve the unexpired term of the predecessor.\nNo person shall be appointed or designated unless he is a natural-born Filipino citizen, of good moral character, of unquestionable integrity, and of recognized competence in relevant fields including, but not limited to, economics, management, international relations, law or engineering, preferably naval or aeronautical.\nThe chairman and president of the Conversion Authority shall have a fixed term of six (6) years.\nAll procedural matters in the conduct of board meetings shall be prescribed in its internal rules.\nMembers of the Board shall receive a per diem of not more than Five thousand pesos (P5,000) for every board meeting: Provided, however, That the per diem collected per month does not exceed the equivalent of four (4) meetings: Provided, further, That the amount of per diem for every board meeting may be increased by the President but such amount shall not be increased within two (2) years after its last increase."}},{"id":"PH-H5715-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Functions of the Board. - The Board of Directors shall be the policy-making body of the Conversion Authority and shall perform the following functions:\na. Determine the organizational structure of the Conversion Authority, define the duties and responsibilities of all officials and employees and adopt a compensation and benefit scheme at least equivalent to that of the Central Bank of the Philippines:\nb. Appoint all Officials down to the third level and authorize the president of the Conversion Authority to appoint all others: Provided, That all appointments shall be on the basis of merit and fitness and all personnel action shall be in pursuance of Civil Service Laws, rules and regulations, except those coterminous employees of the members of the Board;\nc. Prepare the annual and supplemental budgets of the Conversion Authority;\nd. Submit an annual report of the operation of the Conversion Authority to the President of the Philippines, President of the Senate and Speaker of the House of Representatives;\ne. Carry out the purposes of the Conversion Authority with the following terms and references:\n1. As much as possible, major conversion projects shall be undertaken under the complete project turnkey or build-operate-transfer (BOT) scheme, as provided under Republic Act Numbered Sixty-nine hundred and fifty-seven (RA 6957); and\n2. Starting the fourth year of the Conversion Authority-s full operation, a privatization or divestment program of its projects and subsidiaries shall begin under general guidelines prescribed by the President of the Philippines."}},{"id":"PH-H5715-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Duties and Responsibilities of the President of the Conversion Authority. - The president of the Conversation Authority shall have the following duties and responsibilities:\na. To act as Chief Executive Officer of the Conversion Authority;\nb. To execute, administer and implement the policies and measures approved by the Board;\nc. To direct and supervise the operations and administration of the Conversion Authority;\nd. To represent the Conversion Authority in all dealings with offices, agencies and instrumentalities of the Government and with all persons and entities, public or private, domestic or foreign;\ne. To direct and supervise the preparation of the agenda for the meeting of the Board, and to submit for the consideration of the Board such policies and measures as he believes necessary to carry out the purposes and objectives of this Act; and\nf. To exercise such other powers and functions provided in the bylaws and as may be vested in him by the Board."}},{"id":"PH-H5715-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Subic Special Economic Zone. - Subject to the concurrence by resolution of the sangguniang panlungsod of the City of Olongapo and sangguniang bayan of the Municipalities of Subic, Morong and Hermosa, there is hereby created a Special Economic and Free-port Zone consisting of the City of Olongapo and the Municipality of Subic, Province of Zambales, the lands occupied by the Subic Naval Base and its contiguous extensions as embraced, covered, and defined by the 1947 Military Bases Agreement between the Philippines and the United States of America as amended, and within the territorial jurisdiction of the Municipalities of Morong and Hermosa, Province of Bataan, hereinafter referred to as the Subic Special Economic Zone whose metes and bounds shall be delineated in a proclamation to be issued by the President of the Philippines. Within thirty (30) days after the approval of this Act, each local government unit shall submit its resolution of concurrence to join the Subic Special Economic Zone to the Office of the President. Thereafter, the President of the Philippines shall issue a proclamation defining the metes and bounds of the zone as provided herein.\nThe abovementioned zone shall be subject to the following policies:\na. Within the framework and subject to the mandato and limitations of the Constitution and the pertinent provisions of the Local Governemnt Code the Subic Special Economic Zone shall be developed into a self-sustaining, industrial, commercial, financial and investment center to generate employment opportunities in and around the zone and to attract and promote productive foreign investments;\nb. The Subic Special Economic Zone shall be operated and managed as a separate customs territory ensuring free flow or movement of goods and capital within, into and exported out of the Subic Special Economic Zone, as well as provide incentives such as tax and duty-free importations of raw materials, capital and equipment. However, exportation or removal of goods from the territory of the Subic Special Economic Zone to the other parts of the Philippine territory shall be subject to customs duties and taxes under the Customs and Tariff Code and other relevant tax laws of the Philippines;\nc. The provision of existing laws, rules and regulations to the contrary notwithstanding, no taxes, local and national, shall be imposed within the Subic Special Economic Zone. In lieu of paying taxes, three percent (3%) of the gross income earned by all businesses and enterprises within the Subic Special Economic Zone shall be remitted to the National Government, one percent (1%) each to the local government units affected by the declaration of the zone in proportion to their population area, and other factors. In addition, there is hereby established a development fund of one percent (1%) of the gross income earned by all businesses and enterprises within the Subic Special Economic Zone to be utilized for the development of municipalities outside the City of Olongapo and the Municipality of Subic, and other municipalities contiguous to the base areas.\nIn case of conflict between national and local laws with respect to tax exemption privileges in the Subic Special Economic Zone, the same shall be resolved in favor of the latter;\nd. No exchange control policy shall be applied and free markets for foreign exchange, gold, securities and future shall be allowed and maintained in the Subic Special Economic Zone;\ne. The Central Bank, through the Monetary Board, shall supervise and regulate the operations of banks and other financial institutions within the Subic Special Economic Zone;\nf. Banking and finance shall be liberalized with the establishment of foreign currency depository units of local commercial banks and offshore banking units of foreign banks with minimum Central Bank regulation;\ng. Any investor within the Subic Special Economic Zone whose continuing investment shall not be less than Two hundred fifty thousand dollars ($250,000), his/her spouse and dependent children under twenty-one (21) years of age, shall be granted permanent resident status within the Subic Special Economic Zone. They shall have freedom of ingress and egress to and from the Subic Special Economic Zone without any need of special authorization from the Bureau of Immigration and Deportation. The Subic Bay Metropolitan Authority referred to in Section 13 of this Act may also issue working visas renewable every two (2) years to foreign executives and other aliens possessing highly-technical skills which no Filipino within the Subic Special Economic Zone possesses, as certified by the Department of Labor and Employment. The names of aliens granted permanent residence status and working visas by the Subic Bay Metropolitan Authority shall be reported to the Bureau of Immigration and Deportation within thirty (30) days after issuance thereof;\nh. The defense of the zone and the security of its perimeters shall be the responsibility of the National Government in coordination with the Subic Bay Metropolitan Authority. The Subic Bay Metropolitan Authority shall provide and establish its own internal security and fire-fighting forces; and\ni. Except as herein provided, the local government units comprising the Subic Special Economic Zone shall retain their basic autonomy and identity. The cities shall be governed by their respective charters and the municipalities shall operate and function in accordance with Republic Act No. 7160, otherwise known as the Local Government Code of 1991."}},{"id":"PH-H5715-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The Subic Bay Metropolitan Authority. -\na. Creation of the Subic Bay Metropolitan Authority. - A body corporate to be known as the Subic Bay Metropolitan Authority is hereby created as an operating and implementing arm of the Conversion Authority.\nb. Powers and Functions of the Subic Bay Metropolitan Authority - The Subic Bay Metropolitan Authority, otherwise known as the Subic Authority, shall have the following powers and functions:\n1. To operate, administer, manage and develop the ship repair and ship building facility, container port, oil storage and refueling facility and Cubi Air Base within the Subic Special Economic and Free-port Zone as a free market in accordance with the policies set forth in Section 12 of this Act;\n2. To accept any local or foreign investment, business or enterprise, subject only to such rules and regulations to be promulgated by the Subic Authority in conformity with the policies of the Conversion Authority without prejudice to the nationalization requirements provided for in the Constitution.\n3. To undertake and regulate the establishment, operation and maintenance of utilities, other services and infrastructure in the Subic Special Economic Zone including shipping and related business, stevedoring and port terminal services or concessions, incidental thereto and airport operations in coordination with the Civil Aeronautics Board, and to fix just and reasonable rates, fares, charges and other prices therefor;\n4. To construct, acquire, own, lease, operate and maintain on its own or through contract, franchise, license permits bulk purchase from the private sector and build-operate-transfer scheme or joint-venture the required utilities and infrastructure in coordination with local government units and appropriate government agencies concerned and in conformity with existing applicable laws therefor.\n5. To adopt, alter and use a corporate seal; to contract, lease, sell, dispose, acquire and own properties; to sue and be sued in order to carry out its duties and functions as provided for in this Act and to exercise the power of eminent domain for public use and public purpose;\n6. Within the limitation provided by law, to raise and/or borrow the necessary funds from local and international financial institutions and to issue bonds, promissory notes and other securities for that purpose and to secure the same by guarantee, pledge, mortgage, deed of trust, or assignment of its properties held by the Subic Authority for the purpose of financing its projects and programs within the framework and limitations of this Act;\n7. To operate directly or indirectly or license tourism-related activities subject to priorities and standards set by the Subic Authority including games and amusements, exempt horse racing, dog racing and casino gambling which shall continue to be licensed by the Philippine Amusement and Gaming Corporation (PAGCOR) upon recommendation of the Conversion Authority; to maintain and preserve the forested areas as a national park;\n8. To authorize the establishment of appropriate educational and medical institutions;\n9. To protect, maintain and develop the virgin forests within the baselands which will be proclaimed as a national park and subject to a permanent total log ban, and for this purpose, the rules and regulations of the Department of Environment and Natural Resources and other government agencies directly involved in the above functions shall be implemented by the Subic Authority;\n10. To adopt and implement measures and standards for environmental pollution control of all areas within its territory, including, but not limited to all bodies of water and to enforce the same. For which purpose the Subic Authority shall create an Ecology Center; and\n11. To exercise such powers as may be essential, necessary or incidental to the powers granted to it hereunder as well as to carry out the policies and objectives of this Act.\nc. Board of Directors - The powers of the Subic Authority shall be vested in and exercised by a Board of Directors, hereinafter referred to as the Board, which shall be composed of fifteen (15) members, to wit:\n1. Representatives of the local government units that concur to join the Subic Special Economic Zone;\n2. Two (2) representatives from the National Government;\n3. Five (5) representatives from the private sector coming from the present naval stations, public works center, ship repair facility, naval supply depot and naval air station; and\n4. The remaining balance to complete the Board shall be composed of representatives from the business and investment sectors.\nThe chairman and the members of the Board shall be appointed by the President to serve for a term of six (6) years, unless sooner removed for cause except for the representatives of the local government units who shall serve for a term of three (3) years. In case of removal for cause, the replacement shall serve only the unexpired portion of the term.\nNo person shall be appointed as a member of the Board unless he is a Filipino citizen, of good moral character, and of recognized competence in relevant fields including, but not limited to economics, management, international relations, law or engineering. Preference in the appointment of the members of the Board shall be given to residents within the Subic Special Economic Zone.\nMembers of the Board shall receive a per diem of not more than Five thousand pesos (P5,000)) for every board meeting: Provided, however, That the per diem collected per month does not exceed the equivalent of four (4) meetings: Provided, further, That the amount of per diem for every board meeting may be increased by the President: Provided, finally, That the amount of per diem shall not be increased within two (2) years after its last increase.\nd. Chairman/Administrator - The President shall appoint a professional manager as administrator of the Subic Authority with a compensation to be determined by the Board subject to the approval of the Secretary of Budget, who shall be the ex officio chairman of the Board and who shall serve as the chief executive officer of the Subic Authority: Provided,however, That for the first year of its operations from the effectivity of this Act, the mayor of the City of Olongapo shall be appointed as the chairman and chief executive officer of the Subic Authority.\ne. Capitalization - The Subic Authority shall have an authorized capital stock of Twenty billion pesos (P20,000,000,000) divided into twenty thousand (20,000) no-par shares fully subscribed and paid up by the Republic of the Philippines with:\n1. All lands embraced, covered and defined in Section 12 hereof, as well as permanent improvements and fixtures upon proper inventory not otherwise alienated, conveyed, or transferred to another government agency.\n2. All other assets which the President may transfer to the Subic Authority as part of the equity contribution of the Government; and\n3. Cash contribution by the Government in the amount of Three hundred million pesos (P300,000,000) a year for the next three (3) years, which is hereby appropriated out of any fund in the National Treasury not otherwise appropriated."}},{"id":"PH-H5715-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Relationship with the Conversion Authority and the Local Government Units.\na. The provisions of existing laws, rules and regulations to the contrary notwithstanding, the Subic Authority shall exercise administrative powers, rule-making and disbursement of funds over the Subic Special Economic Zone in conformity with the oversight function of the Conversion Authority.\nb. In case of conflict between the Subic Authority and the local government units concerned on matters affecting the Subic Special Economic Zone other than defense and security, the decision of the Subic Authority shall prevail."}},{"id":"PH-H5715-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Clark and Other Special Economic Zones. - Subject to the concurrence by resolution of the local government units directly affected, the President is hereby authorized to create by executive proclamation a Special Economic Zone covering the lands occupied by the Clark military reservations and its contiguous extensions as embraced, covered and defined by the 1947 Military Bases Agreement between the Philippines and the United States of America, as amended, located within the territorial jurisdiction of Angeles City, Municipalities of Mabalacat and Porac, Province of Pampanga, and the Municipality of Capas, Province of Tarlac, in accordance with the policies as herein provided insofar as applicable to the Clark military reservations.\nThe governing body of the Clark Special Economic Zone shall likewise by established by executive proclamation with such powers and functions exercised by the Export Processing Zone Authority pursuant to Presidential Decree No. 66 as amended.\nThe policies to govern and regulate the Clark Special Economic Zone shall be determined upon consultation with the inhabitants of the local government units directly affected which shall be conducted within six (6) months upon approval of this Act.\nSimilarly, subject to the concurrence by resolution of the local government units directly affected, the President shall create other Special Economic Zones, in the base areas of Wallace Air Station in San Fernando, La Union (excluding areas designated for communications, advance warning and radar requirements of the Philippine Air Force to be determined by the Conversion Authority) and Camp John Hay in the City of Baguio.\nUpon recommendation of the Conversion Authority, the President is likewise authorized to create Special Economic Zones covering the Municipalities of Morong, Hermosa, Dinalupihan, Castillejos, and San Marcelino."}},{"id":"PH-H5715-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Subsidiaries. - The Conversion Authority shall have the power to form, establish, organize and maintain a subsidiary corporation or corporations. Such subsidiary or subsidiaries shall be formed in accordance with the Philippine Corporation Law and existing rules and regulations promulgated by the Securities and Exchange Commission, unless otherwise provided in this Act. In all cases, the Conversion Authority shall own initially at least fifty-one per centum (51%) of the capital stock of a subsidiary. The Conversion Authority shall also initially have the majority of the Board of Directors of the subsidiaries, of which at least one (1) director shall be the chairman of the Conversion Authority and a second director shall be the president of the Conversion Authority or his designated representative.\nSuch subsidiaries shall be exempt from the coverage of the Civil Service Laws, rules and regulations."}},{"id":"PH-H5715-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Supervision. - The Conversion Authority shall be under the direct control and supervision of the Office of the President for purposes of policy direction and coordination."}},{"id":"PH-H5715-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Legal Counsel. - Without prejudice to the hiring of an outside counsel, the Government Corporate Counsel shall be the ex officio legal counsel of the Conversion Authority, the governing boards of the Special Economic Zones and the subsidiaries wherein the Conversion Authority owns the majority of the shares of stocks, and for this purpose he may designate a full time representative whose compensation shall be approved by the Board."}},{"id":"PH-H5715-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Auditor. - The Commission on Audit shall appoint a representative who shall be the full time auditor of the Conversion Authority, its subsidiaries and the Special Economic Zones and such personnel as may be necessary to assist said representative in the performance of his duties. He is mandated to impose pre-audit within thirty (30) days after submission of all proposed substantial sales, transfers, and alienations of property. He shall likewise render a full report thereof to Congress every sixty (60) days. The salaries of the auditor and his staff shall be approved by the Board."}},{"id":"PH-H5715-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Interim Capacity. - Except for the chairman of the Subic Authority, the chairman and other members of the Board of the Convention Authority and the Subic Authority shall act in an interim capacity and shall serve until the 31st of July 1992 or until such time that their successors shall have been duly appointed."}},{"id":"PH-H5715-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Injunction and Restraining Order. - The implementation of the projects for the conversion into alternative productive uses of the military reservations are urgent and necessary and shall not be restrained or enjoined except by an order issued by the Supreme Court of the Philippines."}},{"id":"PH-H5715-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Separability Clause . - If any provision of this Act shall be held unconstitutional or invalid, the other provisions not otherwise affected shall remain in full force and effect."}},{"id":"PH-H5715-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Repealing Clause . - All laws, executive issuances or parts thereof which are inconsistent herewith are hereby repealed or amended accordingly."}},{"id":"PH-H5715-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Effectivity Clause. - This Act shall take effect upon its publication in at least one (1) newspaper of general circulation.\nApproved, March 13, 1992."}}],"pack":"ph-p81","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Accelerating the Conversion of Military Revervations Into Other Productive Uses, Creating the Bases Conversion and Development Authority for This Purpose, Providing Funds Therefor and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5716"] = {"id":"PH-H5716","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7228_1992.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"设立萨兰加尼省的法案","en":"An Act Creating the Province of Sarangani","orig":"An Act Creating the Province of Sarangani"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7228","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-16","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7228_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5716-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Municipalities of Alabel, Glan, Maasin, Maitum, Malapatan, Malungon, and Kiamba are hereby segregated from the Province of South Cotabato and constituted into a separate province to be known as Sarangani. The present Province of South Cotabato minus the territory comprising the municipalities abovementioned shall continue to be known as South Cotabato."}},{"id":"PH-H5716-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Except as otherwise herein provided, all provisions of law now or hereafter applicable to regularly organized provinces shall be applicable to the Province of Sarangani."}},{"id":"PH-H5716-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The provincial capital of Sarangani shall be the Municipality of Alabel, and the capitol building and all other national and provincial offices in the new province shall be established within the government lots thereat."}},{"id":"PH-H5716-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The creation of the Province of Sarangani as provided in this Act shall be subject to the approval of the majority of the votes cast by the voters of the affected areas in a plebiscite to be conducted by the Commission on Elections within one hundred twenty (120) days from the date of the effectivity of the law as provided in Section 10 of the Local Government Code of 1991: Provided, That, should the voters favor such division, the election of the provincial officials shall be held simultaneously with the forthcoming synchronized national and local elections in May 1992: Provided,further, That, should such election be not possible, the provincial officials shall be elected in special election to be held within sixty (60) days after the plebiscite."}},{"id":"PH-H5716-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Upon the effectivity of this Act, the obligations, funds, assets and other properties of the present Province of South Cotabato shall be divided proportionately between the Province of South Cotabato and the Province of Sarangani by the President of the Philippines upon the recommendation of the Commission on Audit."}},{"id":"PH-H5716-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p81","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Province of Sarangani","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5717"] = {"id":"PH-H5717","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7229_1992.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"批准 Globe Mackay 与 Clavecilla 两家无线电公司合并、移转特许权、延长其期限，并废止第 402 号共和国法若干条款的法案","en":"An Act Approving the Merger Between Globe Mackay Cable and Radio Corporation and Clavecilla Radio System and the Consequent Transfer of the Franchise of Clavecilla Radio System Granted Under Republic Act No. 402, as Amended, to Globe Mackay Cable and Radio Corporation, Extending the Life of Said Franchise, and Repealing Certain Sections of Republic Act No. 402, as Amended","orig":"An Act Approving the Merger Between Globe Mackay Cable and Radio Corporation and Clavecilla Radio System and the Consequent Transfer of the Franchise of Clavecilla Radio System Granted Under Republic Act No. 402, as Amended, to Globe Mackay Cable and Radio Corporation, Extending the Life of Said Franchise, and Repealing Certain Sections of Republic Act No. 402, as Amended"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 7229","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-19","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7229_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5717-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The merger between Globe Mackay Cable and Radio Corporation and Clavecilla Radio System, with Globe Mackay Cable and Radio Corporation thenceforth known as GMCR, Inc., and hereinafter referred to as the grantee as the surviving corporation, is hereby approved."}},{"id":"PH-H5717-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The transfer of the franchise of Clavecilla Radio System under Republic Act No. 402, as amended by Republic Act Nos. 1618 and 4540, as well as all the rights, privileges and licenses arising therefrom with the exception of broadcasting, to the grantee as a consequence of the merger between Globe Mackay Cable and Radio Corporation and Clavecilla Radio System, is hereby approved."}},{"id":"PH-H5717-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the existing stations or other stations which may be established in accordance with law of other telecommunications services grantees without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H5717-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee shall provide reasonable public service time to enable the Government, through the stations of the grantee, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation to the detriment of the public interest or to incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H5717-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast and/or telecast from its stations; but if any such speech, play, act or scene, or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play, act or scene, or other matter: Provided, That the grantee, during any broadcast and/or telecast, shall cut off from the air the speech, play, act or scene, or other matter being broadcast/telecast if the tendency thereof is to propose and/or incite treason, rebellion or sedition; or the language used therein or the theme thereof is indecent or immoral; and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H5717-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or entity, nor merge with any other corporation or entity without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines, except when the transfer is done through a stock exchange transaction. Any person or entity to which this franchise is validly sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H5717-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall comply with and be subject to the provisions of such general telecommunications and broadcast policy laws as may hereafter be enacted."}},{"id":"PH-H5717-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of this franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H5717-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The life of the franchise granted under Republic Act No. 402, as amended by Republic Act Nos. 1618 and 4540, is hereby extended to 24 December 2030 so as to make it coterminous with the term of the franchise of Globe Mackay Cable and Radio Corporation granted under Batas Pambansa Blg. 95."}},{"id":"PH-H5717-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Sections 8 and 13 of Republic Act No. 402, as amended by Republic Act Nos. 1618 and 4540, are hereby repealed in their entirety."}},{"id":"PH-H5717-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"All the other provisions of Republic Act No. 402, as amended by Republic Act Nos. 1618 and 4540, and the provisions of Batas Pambansa Blg. 95 which are not inconsistent with the provisions of this Act and are still unrepealed shall continue to be in full force and effect."}},{"id":"PH-H5717-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p81","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Approving the Merger Between Globe Mackay Cable and Radio Corporation and Clavecilla Radio System and the Consequent Transfer of the Franchise of Clavecilla Radio System Granted Under Republic Act No. 402, as Amended, to Globe Mackay Cable and Radio Corporation, Extending the Life of Said Franchise, and Repealing Certain Sections of Republic Act No. 402, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5718"] = {"id":"PH-H5718","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7230_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定主要军种司令、副参谋长与南部司令部司令为中将衔，北吕宋、南吕宋、米沙鄢与西部司令部司令及菲律宾军事学院院长为少将衔","en":"An Act Authorizing the Rank of Lieutenant General/Vice Admiral to the Positions of Commanders of the Major Services, the Deputy Chief of Staff and the Southern Command and the Rank of Major General/Rear Admiral to the Positions of Commanders of the Northern Luzon Command, the Southern Luzon Command, the Visayas Command, and the Western Command, and the Superintendent of the Philippine Military Academy.","orig":"An Act Authorizing the Rank of Lieutenant General/Vice Admiral to the Positions of Commanders of the Major Services, the Deputy Chief of Staff and the Southern Command and the Rank of Major General/Rear Admiral to the Positions of Commanders of the Northern Luzon Command, the Southern Luzon Command, the Visayas Command, and the Western Command, and the Superintendent of the Philippine Military Academy."},"level":"law","status":"active","topics":["defence"],"docNumber":"Republic Act No. 7230","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7230_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5718-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The rank of lieutenant general/vice admiral is authorized to the positions of Commanders of the Major Services, the Deputy Chief of Staff and the Southern Command and the rank of major general/rear admiral to the positions of Commanders of the Northern Luzon Command, the Southern Luzon Command, the Visayas Command, and the Western Command, and the Superintendent of the Philippine Military Academy of the Armed Forces of the Philippines."}},{"id":"PH-H5718-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Presidential Decree No. 360, as amended by Presidential Decree No. 1769, and all other laws, proclamations, decrees, letters of instruction, executive orders, rules and regulations and other issuances, or parts thereof, which are inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H5718-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p81","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the Rank of Lieutenant General/Vice Admiral to the Positions of Commanders of the Major Services, the Deputy Chief of Staff and the Southern Command and the Rank of Major General/Rear Admiral to the Positions of Commanders of the Northern Luzon Command, the Southern Luzon Command, the Visayas Command, and the Western Command, and the Superintendent of the Philippine Military Academy.","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
